-- ============================================================
-- Helper functions (SECURITY DEFINER so they bypass RLS on team_members
-- and avoid policy recursion). They only report on the calling user.
-- ============================================================

create function public.is_team_member(p_team_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = auth.uid()
  );
$$;

create function public.is_team_editor(p_team_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.team_members tm
    where tm.team_id = p_team_id
      and tm.user_id = auth.uid()
      and tm.role = 'editor'
  );
$$;

revoke all on function public.is_team_member(bigint) from public, anon;
revoke all on function public.is_team_editor(bigint) from public, anon;
grant execute on function public.is_team_member(bigint) to authenticated, service_role;
grant execute on function public.is_team_editor(bigint) to authenticated, service_role;

-- ============================================================
-- Enable RLS
-- ============================================================

alter table public.teams        enable row level security;
alter table public.team_members enable row level security;
alter table public.documents    enable row level security;

-- ============================================================
-- Grants / revokes
-- R8: anon gets nothing. R7: no writes to teams / memberships.
-- ============================================================

revoke all on table public.teams        from anon, authenticated;
revoke all on table public.team_members from anon, authenticated;
revoke all on table public.documents    from anon, authenticated;

grant select on table public.teams        to authenticated;
grant select on table public.team_members to authenticated;

grant select, insert, delete on table public.documents to authenticated;
-- id and created_by can never be changed by app users
grant update (team_id, title, deleted_at) on table public.documents to authenticated;

grant all on table public.teams        to service_role;
grant all on table public.team_members to service_role;
grant all on table public.documents    to service_role;

-- ============================================================
-- teams (R1)
-- ============================================================

create policy teams_select_member
  on public.teams
  for select
  to authenticated
  using ( public.is_team_member(id) );

-- ============================================================
-- team_members (R2) - only own rows; no write policies (R7)
-- ============================================================

create policy team_members_select_own
  on public.team_members
  for select
  to authenticated
  using ( user_id = auth.uid() );

-- ============================================================
-- documents
-- ============================================================

-- R3: members read non-deleted documents of their teams
create policy documents_select_member
  on public.documents
  for select
  to authenticated
  using (
    deleted_at is null
    and public.is_team_member(team_id)
  );

-- R4: editors create documents in their teams, as themselves
create policy documents_insert_editor
  on public.documents
  for insert
  to authenticated
  with check (
    created_by = auth.uid()
    and deleted_at is null
    and public.is_team_editor(team_id)
  );

-- R5: editors edit any (non-deleted) document of their teams;
-- result must remain in a team where the user is an editor.
create policy documents_update_editor
  on public.documents
  for update
  to authenticated
  using (
    deleted_at is null
    and public.is_team_editor(team_id)
  )
  with check (
    public.is_team_editor(team_id)
    and (deleted_at is null or created_by = auth.uid())
  );

-- R6: only the creator can (hard) delete
create policy documents_delete_creator
  on public.documents
  for delete
  to authenticated
  using (
    created_by = auth.uid()
    and deleted_at is null
    and public.is_team_member(team_id)
  );

-- ============================================================
-- Trigger: enforce immutability of created_by / id and that only the
-- creator may soft-delete (set deleted_at) for app users.
-- ============================================================

create function public.documents_guard_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if coalesce(auth.role(), '') in ('authenticated', 'anon') then
    if new.id is distinct from old.id then
      raise exception 'document id cannot be changed';
    end if;
    if new.created_by is distinct from old.created_by then
      raise exception 'created_by cannot be changed';
    end if;
    if old.deleted_at is not null then
      raise exception 'deleted documents cannot be modified';
    end if;
    if new.deleted_at is not null
       and old.created_by is distinct from auth.uid() then
      raise exception 'only the creator can delete this document';
    end if;
  end if;
  return new;
end;
$$;

create trigger documents_guard_update
  before update on public.documents
  for each row
  execute function public.documents_guard_update();
