-- =========================================================
-- Guard trigger on documents:
--  * created_by is immutable for app users (keeps R6 meaningful)
--  * only the creator may soft-delete (set deleted_at)  (R6)
--  * deleted documents cannot be restored by app users  (R3)
-- Service role / server-side code (no auth.uid()) is unaffected (R9).
-- =========================================================
create or replace function public.documents_guard_update()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.role() = 'service_role' or auth.uid() is null then
    return new;
  end if;

  if new.created_by is distinct from old.created_by then
    raise exception 'created_by cannot be changed';
  end if;

  if new.deleted_at is distinct from old.deleted_at then
    if old.deleted_at is not null then
      raise exception 'deleted documents cannot be restored';
    end if;
    if old.created_by is distinct from auth.uid() then
      raise exception 'only the creator can delete this document';
    end if;
  end if;

  return new;
end;
$$;

revoke all on function public.documents_guard_update() from public, anon, authenticated;

create trigger documents_guard_update
before update on public.documents
for each row
execute function public.documents_guard_update();

-- Soft-delete helper for creators (avoids SELECT-visibility issues on UPDATE)
create or replace function public.soft_delete_document(p_document_id bigint)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.documents d
     set deleted_at = now()
   where d.id = p_document_id
     and d.deleted_at is null
     and d.created_by = auth.uid()
     and public.is_team_member(d.team_id);
  if not found then
    raise exception 'document not found or not allowed';
  end if;
end;
$$;

revoke all on function public.soft_delete_document(bigint) from public, anon;
grant execute on function public.soft_delete_document(bigint) to authenticated, service_role;

