        raise exception 'id cannot be changed';
      end if;
      if new.deleted_at is distinct from old.deleted_at
         and old.created_by is distinct from auth.uid() then
        raise exception 'only the creator can delete a document';
      end if;
    end if;
  end if;
  return new;
end;
$$;

