    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
  );
$$;

create or replace function public.is_org_admin(p_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id = auth.uid()
      and m.role = 'admin'
  );
$$;

-- Resolve a storage object path "<project id>/<file name>" to the project's org
-- and check whether the current user is a member / admin of it.
create or replace function public.project_file_org(p_object_name text)
returns bigint
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_seg text;
  v_org bigint;
begin
  if p_object_name is null then
    return null;
  end if;
  -- Exactly two path segments: <project id>/<file name>
  if array_length(string_to_array(p_object_name, '/'), 1) <> 2 then
    return null;
  end if;
  v_seg := split_part(p_object_name, '/', 1);
  if split_part(p_object_name, '/', 2) = '' then
    return null;
  end if;
  if v_seg !~ '^[0-9]{1,18}$' then
    return null;
  end if;
  select p.org_id into v_org
  from public.projects p
  where p.id = v_seg::bigint;
  return v_org;
end;
$$;

