grant select on table public.posts to anon;
grant select on table public.comments to anon;

-- Signed-in users
grant select, insert, update, delete on table public.posts to authenticated;
grant select, insert, delete on table public.comments to authenticated;   -- R6: no update on comments

-- R8: service role keeps full access (it also bypasses RLS)
grant all on table public.posts to service_role;
grant all on table public.comments to service_role;

-- ===================== posts =====================

-- R1: anyone can read live posts
create policy posts_select_live
  on public.posts
  for select
  to anon, authenticated
  using (
    published_at is not null
    and published_at <= now()
    and (unpublish_at is null or unpublish_at > now())
  );

-- R2: authors can read all of their own posts
create policy posts_select_own
  on public.posts
  for select
  to authenticated
  using (author_id = (select auth.uid()));

-- R3: create posts only as yourself
create policy posts_insert_own
  on public.posts
  for insert
  to authenticated
  with check (author_id = (select auth.uid()));

-- R3: edit only your own posts, and cannot reassign authorship
create policy posts_update_own
  on public.posts
  for update
  to authenticated
  using (author_id = (select auth.uid()))
  with check (author_id = (select auth.uid()));

-- R3: delete only your own posts
create policy posts_delete_own
  on public.posts
  for delete
  to authenticated
  using (author_id = (select auth.uid()));

-- ===================== comments =====================
-- The subqueries on public.posts are themselves filtered by the posts
-- RLS policies above, so "exists" means "the caller can read that post".

-- R4: comments visible exactly to those who can read the parent post
create policy comments_select_readable_post
  on public.comments
  for select
  to anon, authenticated
  using (
    exists (
      select 1 from public.posts p
      where p.id = comments.post_id
    )
  );

