  on public.comments
  for insert
  to authenticated
  with check (
    author_id = (select auth.uid())
    and exists (
      select 1 from public.posts p
      where p.id = comments.post_id
    )
  );

-- R6: comment authors delete their own; post authors delete any on their posts
create policy comments_delete_own_or_post_author
  on public.comments
  for delete
  to authenticated
  using (
    author_id = (select auth.uid())
    or exists (
      select 1 from public.posts p
      where p.id = comments.post_id
        and p.author_id = (select auth.uid())
    )
  );

