alter table public.employees enable row level security;

-- Helper: is the current user an employee? (security definer avoids RLS recursion)
create or replace function public.is_employee()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.employees e
    where e.user_id = auth.uid()
  );
$$;

-- Helper: is the current user an HR employee?
create or replace function public.is_hr()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.employees e
    where e.user_id = auth.uid()
      and e.department = 'HR'
  );
$$;

revoke all on function public.is_employee() from public, anon;
revoke all on function public.is_hr() from public, anon;
grant execute on function public.is_employee() to authenticated, service_role;
grant execute on function public.is_hr() to authenticated, service_role;

-- R2 / R3: read own row, or HR reads all
create policy employees_select_own_or_hr
  on public.employees
  for select
  to authenticated
  using (user_id = auth.uid() or public.is_hr());

-- R3 / R5: only HR may update any row
create policy employees_update_hr
  on public.employees
  for update
  to authenticated
  using (public.is_hr())
  with check (public.is_hr());

-- Table privileges: anon gets nothing; authenticated limited to select/update (RLS-filtered)
revoke all on table public.employees from public, anon, authenticated;
grant select, update on table public.employees to authenticated;
grant all on table public.employees to service_role;

-- R1 / R7: directory view (runs as owner, exposes only non-sensitive columns)
create view public.employee_directory
with (security_invoker = false, security_barrier = true)
as
  select e.id, e.full_name, e.department
  from public.employees e
  where public.is_employee()
     or auth.role() = 'service_role';

-- R6: no anon access to the directory
revoke all on table public.employee_directory from public, anon, authenticated;
grant select on table public.employee_directory to authenticated;
grant select on table public.employee_directory to service_role;
