-- Enable RLS
-- =========================================================
alter table public.accounts    enable row level security;
alter table public.files       enable row level security;
alter table public.file_shares enable row level security;

-- =========================================================
-- Privileges (R6, R7, R1: owner_id immutable via column grants)
-- =========================================================
revoke all on public.accounts    from anon, authenticated;
revoke all on public.files       from anon, authenticated;
revoke all on public.file_shares from anon, authenticated;

grant select on public.accounts to authenticated;

grant select, delete on public.files to authenticated;
grant insert (id, owner_id, name) on public.files to authenticated;
grant update (name) on public.files to authenticated;

grant select, insert, update, delete on public.file_shares to authenticated;

grant all on public.accounts    to service_role;
grant all on public.files       to service_role;
grant all on public.file_shares to service_role;

-- =========================================================
-- Helper functions (security definer to avoid RLS recursion)
-- =========================================================
create or replace function public.rls_is_active_user()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select auth.uid() is not null
     and not coalesce(
       (select a.suspended from public.accounts a where a.user_id = auth.uid()),
       false
     );
$$;

create or replace function public.rls_owns_file(p_file_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.files f
    where f.id = p_file_id
      and f.owner_id = auth.uid()
  );
$$;

create or replace function public.rls_has_active_share(p_file_id bigint, p_need_edit boolean)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.file_shares s
    where s.file_id = p_file_id
      and s.shared_with = auth.uid()
      and (s.expires_at is null or s.expires_at > now())
      and (not p_need_edit or s.can_edit)
  );
$$;

revoke all on function public.rls_is_active_user() from public, anon;
revoke all on function public.rls_owns_file(bigint) from public, anon;
revoke all on function public.rls_has_active_share(bigint, boolean) from public, anon;
grant execute on function public.rls_is_active_user() to authenticated, service_role;
grant execute on function public.rls_owns_file(bigint) to authenticated, service_role;
grant execute on function public.rls_has_active_share(bigint, boolean) to authenticated, service_role;

-- =========================================================
-- accounts (R6)
-- =========================================================
create policy accounts_select_own
  on public.accounts
  for select
  to authenticated
  using (user_id = auth.uid());

-- =========================================================
-- files (R1, R2, R3, R5)
-- =========================================================
create policy files_select
  on public.files
  for select
  to authenticated
  using (
    public.rls_is_active_user()
    and (
      owner_id = auth.uid()
      or public.rls_has_active_share(id, false)
    )
  );

create policy files_insert_owner
  on public.files
  for insert
  to authenticated
  with check (
    public.rls_is_active_user()
    and owner_id = auth.uid()
  );

create policy files_update_owner
  on public.files
  for update
  to authenticated
  using (
    public.rls_is_active_user()
    and owner_id = auth.uid()
  )
  with check (
    public.rls_is_active_user()
    and owner_id = auth.uid()
  );

create policy files_update_editor
  on public.files
  for update
  to authenticated
  using (
    public.rls_is_active_user()
    and public.rls_has_active_share(id, true)
  )
  with check (
    public.rls_is_active_user()
    and public.rls_has_active_share(id, true)
  );

create policy files_delete_owner
  on public.files
  for delete
  to authenticated
  using (
    public.rls_is_active_user()
    and owner_id = auth.uid()
  );

-- =========================================================
-- file_shares (R4, R5)
-- =========================================================
create policy file_shares_select
  on public.file_shares
  for select
  to authenticated
  using (
    public.rls_is_active_user()
    and (
      shared_with = auth.uid()
      or public.rls_owns_file(file_id)
    )
  );

create policy file_shares_insert_owner
  on public.file_shares
  for insert
  to authenticated
  with check (
    public.rls_is_active_user()
    and public.rls_owns_file(file_id)
  );

create policy file_shares_update_owner
  on public.file_shares
  for update
  to authenticated
