  on public.expenses
  for insert
  to authenticated
  with check (
    submitted_by = (select auth.uid())
    and public.is_department_member(department_id)
    and status = 'pending'
    and decided_by is null
  );

-- R3 (column grants restrict updates to "amount" only)
