-- =========================================================
-- Trigger: never leave an org without an owner (race-safe)
-- =========================================================
create or replace function public.org_members_keep_owner()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org_exists boolean;
  v_other_owners bigint;
begin
  if auth.role() = 'service_role' or auth.uid() is null then
    if tg_op = 'DELETE' then return old; else return new; end if;
  end if;

  if old.role = 'owner'
     and (tg_op = 'DELETE' or new.role <> 'owner' or new.org_id <> old.org_id) then
    -- serialize concurrent owner removals per org
    select true into v_org_exists
    from public.orgs o
    where o.id = old.org_id
    for update;

    -- org itself being deleted (cascade): allow
    if v_org_exists is null then
      if tg_op = 'DELETE' then return old; else return new; end if;
    end if;

    select count(*) into v_other_owners
    from public.org_members m
    where m.org_id = old.org_id
      and m.role = 'owner'
      and m.user_id <> old.user_id;

    if v_other_owners = 0 then
      raise exception 'An organization must keep at least one owner';
    end if;
  end if;

  if tg_op = 'DELETE' then return old; else return new; end if;
end;
$$;

