-- Race-safe guard: an organization must always keep at least one owner
create function public.org_members_keep_owner()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_remaining bigint;
begin
  if auth.role() = 'service_role' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if old.role = 'owner'
     and (tg_op = 'DELETE' or new.role <> 'owner' or new.org_id <> old.org_id or new.user_id <> old.user_id) then
    -- serialize owner removals per org
    perform 1 from public.orgs o where o.id = old.org_id for update;
    if not found then
      -- org is being deleted (cascade); allow
      return case when tg_op = 'DELETE' then old else new end;
    end if;

    select count(*) into v_remaining
    from public.org_members m
    where m.org_id = old.org_id
      and m.role = 'owner'
      and m.user_id <> old.user_id;

    if v_remaining = 0 then
      raise exception 'An organization must keep at least one owner';
    end if;
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;

