-- Products: read-only for app roles (R1, R2)
revoke all on table public.products from anon, authenticated;
grant select on table public.products to anon, authenticated;

-- Cart items: no access for anonymous visitors (R5); signed-in users get DML, filtered by RLS (R3, R4)
revoke all on table public.cart_items from anon, authenticated;
grant select, insert, update, delete on table public.cart_items to authenticated;

-- ===== Helper =====
create or replace function public.is_product_active(p_product_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.products p
    where p.id = p_product_id
      and p.is_active
  );
$$;

revoke all on function public.is_product_active(bigint) from public;
grant execute on function public.is_product_active(bigint) to authenticated;

-- ===== Products policies =====
-- R1: anyone can read active products; inactive ones only via service_role (bypasses RLS)
create policy "products_select_active"
  on public.products
  for select
  to anon, authenticated
  using (is_active);

-- R2: no insert/update/delete policies on products for app roles.

-- ===== Cart items policies =====
-- R3: signed-in users read only their own cart items
create policy "cart_items_select_own"
  on public.cart_items
  for select
  to authenticated
  using (user_id = (select auth.uid()));

-- R4: add items to own cart, only for active products
create policy "cart_items_insert_own_active"
  on public.cart_items
  for insert
  to authenticated
  with check (
    user_id = (select auth.uid())
    and public.is_product_active(product_id)
  );

-- R4: change items in own cart, only for active products (also used by upsert ON CONFLICT DO UPDATE)
create policy "cart_items_update_own_active"
  on public.cart_items
  for update
  to authenticated
  using (
    user_id = (select auth.uid())
    and public.is_product_active(product_id)
  )
  with check (
    user_id = (select auth.uid())
    and public.is_product_active(product_id)
  );

-- R4: remove items from own cart, only for active products
create policy "cart_items_delete_own_active"
  on public.cart_items
  for delete
  to authenticated
  using (
    user_id = (select auth.uid())
    and public.is_product_active(product_id)
  );

-- R6: service_role bypasses RLS and retains full access.
grant all on table public.products to service_role;
grant all on table public.cart_items to service_role;
