-- Enable RLS on all application tables
alter table public.patients  enable row level security;
alter table public.care_team enable row level security;
alter table public.records   enable row level security;

-- Helper functions (SECURITY DEFINER to avoid cross-table RLS recursion).
-- Access derives only from patients / care_team rows, never from user metadata (R6).
create or replace function public.is_patient_owner(p_patient_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.patients p
    where p.id = p_patient_id
      and p.user_id = auth.uid()
  );
$$;

create or replace function public.is_care_doctor(p_patient_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.care_team ct
    where ct.patient_id = p_patient_id
      and ct.doctor_id = auth.uid()
  );
$$;

create or replace function public.is_aal2()
returns boolean
language sql
stable
set search_path = ''
as $$
  select coalesce(auth.jwt() ->> 'aal', '') = 'aal2';
$$;

revoke all on function public.is_patient_owner(bigint) from public, anon;
revoke all on function public.is_care_doctor(bigint)   from public, anon;
revoke all on function public.is_aal2()                from public, anon;
grant execute on function public.is_patient_owner(bigint) to authenticated, service_role;
grant execute on function public.is_care_doctor(bigint)   to authenticated, service_role;
grant execute on function public.is_aal2()                to authenticated, service_role;

-- Table privileges
-- R7: anon gets nothing
revoke all on table public.patients  from anon;
revoke all on table public.care_team from anon;
revoke all on table public.records   from anon;

-- authenticated: read-only, plus column-restricted insert on records (R3, R4, R5)
revoke all on table public.patients  from authenticated;
revoke all on table public.care_team from authenticated;
revoke all on table public.records   from authenticated;

grant select on table public.patients  to authenticated;
grant select on table public.care_team to authenticated;
grant select on table public.records   to authenticated;
grant insert (patient_id, author_id, note) on table public.records to authenticated;

-- R8: service role keeps full access (bypasses RLS)
grant all on table public.patients  to service_role;
grant all on table public.care_team to service_role;
grant all on table public.records   to service_role;

-- patients: R1 (own row, any aal) and R2 (care-team doctor, aal2 only)
create policy patients_select_own_or_care_team
  on public.patients
  for select
  to authenticated
  using (
    user_id = auth.uid()
    or (public.is_aal2() and public.is_care_doctor(id))
  );

-- care_team: R5 (rows involving the user as patient or doctor); no write policies
create policy care_team_select_involved
  on public.care_team
  for select
  to authenticated
  using (
    doctor_id = auth.uid()
    or public.is_patient_owner(patient_id)
  );

-- records: R1 / R2 read
create policy records_select_own_or_care_team
  on public.records
  for select
