-- R1: users can read only their own wallet
create policy wallets_select_own
  on public.wallets
  for select
  to authenticated
  using (user_id = (select auth.uid()));

-- R2: users can read transfers they sent or received
create policy transfers_select_participant
  on public.transfers
  for select
  to authenticated
  using (
    from_user = (select auth.uid())
    or to_user = (select auth.uid())
  );

-- R4: the send_points RPC
create or replace function public.send_points(p_to uuid, p_amount integer)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_sender_balance integer;
  v_recipient_exists boolean := false;
  v_sender_exists boolean := false;
  v_id bigint;
  r record;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'amount must be positive' using errcode = '22023';
  end if;

  if p_to is null then
    raise exception 'recipient required' using errcode = '22023';
  end if;

  if p_to = v_uid then
    raise exception 'cannot send points to yourself' using errcode = '22023';
  end if;

  -- Lock both wallets in a deterministic order to avoid deadlocks and races
  for r in
    select w.user_id, w.balance
    from public.wallets w
    where w.user_id in (v_uid, p_to)
    order by w.user_id
    for update
  loop
    if r.user_id = v_uid then
      v_sender_exists := true;
      v_sender_balance := r.balance;
    elsif r.user_id = p_to then
      v_recipient_exists := true;
    end if;
  end loop;

  if not v_recipient_exists then
    raise exception 'recipient has no wallet' using errcode = 'P0002';
  end if;

  if not v_sender_exists or v_sender_balance < p_amount then
    raise exception 'insufficient points' using errcode = 'P0001';
  end if;

  update public.wallets
     set balance = balance - p_amount
   where user_id = v_uid;

  update public.wallets
     set balance = balance + p_amount
   where user_id = p_to;

  insert into public.transfers (from_user, to_user, amount, created_at)
  values (v_uid, p_to, p_amount, now())
  returning id into v_id;

  return v_id;
end;
$$;

