-- Checks the borrowing limits. Must see all loans (not just the caller's),
-- hence security definer. Volatile so each query gets a fresh snapshot
-- after the advisory locks taken by the trigger below.
create or replace function public.can_borrow(p_book_id bigint)
returns boolean
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_copies integer;
  v_book_active integer;
  v_user_active integer;
begin
  if v_uid is null or p_book_id is null then
    return false;
  end if;

  select b.copies into v_copies from public.books b where b.id = p_book_id;
  if v_copies is null then
    return false;
  end if;

  select count(*) into v_book_active
  from public.loans l
  where l.book_id = p_book_id and l.returned_on is null;

  if v_book_active >= v_copies then
    return false;
  end if;

  select count(*) into v_user_active
  from public.loans l
  where l.borrower_id = v_uid and l.returned_on is null;

  if v_user_active >= 3 then
    return false;
  end if;

  return true;
end;
$$;

