-- =========================================================
-- Race-safe enforcement of borrowing limits (R3)
-- Locks the book row and the borrower, then re-checks with a
-- fresh snapshot (plpgsql volatile function) before insert.
-- =========================================================
create or replace function public.loans_enforce_borrow()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_copies integer;
  v_active_book bigint;
  v_active_user bigint;
begin
  if coalesce(auth.role(), '') = 'service_role' then
    return new;
  end if;

  if new.borrower_id is distinct from auth.uid() then
    raise exception 'loans can only be created for yourself';
  end if;

  if new.returned_on is not null then
    raise exception 'new loans must be active';
  end if;

  -- serialize per book
  select b.copies into v_copies
  from public.books b
  where b.id = new.book_id
  for update;

  if not found then
    raise exception 'book does not exist';
  end if;

  -- serialize per borrower
  perform pg_advisory_xact_lock(hashtextextended('loans_borrower:' || new.borrower_id::text, 0));

  select count(*) into v_active_book
  from public.loans x
  where x.book_id = new.book_id and x.returned_on is null;

  if v_active_book >= v_copies then
    raise exception 'no free copy of this book';
  end if;

  select count(*) into v_active_user
  from public.loans x
  where x.borrower_id = new.borrower_id and x.returned_on is null;

  if v_active_user >= 3 then
    raise exception 'too many active loans';
  end if;

  return new;
end;
$$;

revoke all on function public.loans_enforce_borrow() from public, anon, authenticated;

create trigger loans_enforce_borrow
before insert on public.loans
for each row execute function public.loans_enforce_borrow();

-- Defense in depth for R4: only returned_on may change, once.
create or replace function public.loans_enforce_return()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce(auth.role(), '') = 'service_role' then
    return new;
  end if;

  if old.returned_on is not null then
    raise exception 'returned loans cannot be changed';
  end if;

  if new.id          is distinct from old.id
  or new.book_id     is distinct from old.book_id
  or new.borrower_id is distinct from old.borrower_id
  or new.borrowed_on is distinct from old.borrowed_on then
    raise exception 'only returned_on can be changed';
  end if;

  if new.returned_on is null then
    raise exception 'returned_on must be set';
  end if;

  return new;
end;
$$;

revoke all on function public.loans_enforce_return() from public, anon, authenticated;

create trigger loans_enforce_return
before update on public.loans
for each row execute function public.loans_enforce_return();

