-- ============================================================
-- Capacity enforcement (race-safe: serializes inserts per event)
-- ============================================================
create or replace function public.enforce_rsvp_capacity()
returns trigger
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_capacity integer;
  v_count    integer;
begin
  -- Lock the event row; NO KEY UPDATE conflicts with itself (serializing
  -- concurrent RSVPs to the same event) but not with FK KEY SHARE locks.
  select e.capacity into v_capacity
  from public.events e
  where e.id = new.event_id
  for no key update;

  if v_capacity is null then
    raise exception 'event % does not exist', new.event_id
      using errcode = 'foreign_key_violation';
  end if;

  select count(*) into v_count
  from public.rsvps r
  where r.event_id = new.event_id;

  if v_count >= v_capacity then
    raise exception 'event % is at capacity', new.event_id
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;

