-- =========================================================
-- Capacity enforcement under concurrency (R4)
-- Locks the event row so concurrent RSVPs serialize and the count is accurate.
-- =========================================================
create or replace function public.enforce_rsvp_capacity()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_capacity integer;
  v_count    bigint;
begin
  -- Server-side / service role / direct DB access keeps full access (R7)
  if coalesce(auth.role(), '') not in ('authenticated', 'anon') then
    return new;
  end if;

  select e.capacity into v_capacity
  from public.events e
  where e.id = new.event_id
  for update;

  if v_capacity is null then
    raise exception 'event % not found', new.event_id using errcode = '23503';
  end if;

  select count(*) into v_count
  from public.rsvps r
  where r.event_id = new.event_id;

  if v_count >= v_capacity then
    raise exception 'event % is full', new.event_id using errcode = 'P0001';
  end if;

  return new;
end;
$$;

revoke all on function public.enforce_rsvp_capacity() from public, anon, authenticated;

