-- employees policies (R6, R7)
-- =========================================================
create policy employees_select_authenticated
  on public.employees
  for select
  to authenticated
  using (true);

-- =========================================================
-- leave_requests policies
-- =========================================================

-- R1: own requests, or direct reports' requests
create policy leave_requests_select
  on public.leave_requests
  for select
  to authenticated
  using (
    employee_id = auth.uid()
    or public.is_direct_manager_of(employee_id)
  );

-- R2: create for self only, pending, undecided
create policy leave_requests_insert_own
  on public.leave_requests
  for insert
  to authenticated
  with check (
    employee_id = auth.uid()
    and status = 'pending'
    and decided_by is null
  );

-- R3 / R4 / R5: only pending rows can be updated
create policy leave_requests_update
  on public.leave_requests
  for update
  to authenticated
  using (
    status = 'pending'
    and (
      employee_id = auth.uid()
      or public.is_direct_manager_of(employee_id)
    )
  )
  with check (
    (
      employee_id = auth.uid()
      and status in ('pending', 'cancelled')
      and decided_by is null
    )
    or (
      employee_id <> auth.uid()
      and public.is_direct_manager_of(employee_id)
      and status in ('approved', 'rejected')
      and decided_by = auth.uid()
    )
  );

-- No DELETE policy: requests are never deleted (R5).

-- =========================================================
-- Trigger enforcing old-vs-new transition rules
-- =========================================================
create function public.leave_requests_guard_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- Service role / server-side roles are not bound (R8)
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  if old.status <> 'pending' then
    raise exception 'leave request is no longer pending and cannot be changed';
  end if;

  if new.id is distinct from old.id
     or new.employee_id is distinct from old.employee_id then
    raise exception 'cannot change id or employee of a leave request';
  end if;

  if new.status in ('approved', 'rejected') then
    -- Manager decision (R4)
    if new.employee_id = auth.uid() then
      raise exception 'employees cannot decide their own requests';
    end if;
    if not public.is_direct_manager_of(new.employee_id) then
      raise exception 'only the direct manager can decide this request';
    end if;
    if new.decided_by is distinct from auth.uid() then
      raise exception 'decided_by must be the deciding manager';
    end if;
    if new.starts_on is distinct from old.starts_on
       or new.ends_on is distinct from old.ends_on
       or new.note is distinct from old.note then
      raise exception 'deciding cannot change dates or note';
    end if;
  elsif new.status in ('pending', 'cancelled') then
    -- Employee edit / cancel (R3)
    if new.employee_id is distinct from auth.uid() then
      raise exception 'only the employee can edit or cancel their request';
    end if;
    if new.decided_by is not null then
      raise exception 'decided_by must remain empty';
    end if;
  else
    raise exception 'invalid status transition';
  end if;

  return new;
end;
$$;

revoke all on function public.leave_requests_guard_update() from public;
revoke all on function public.leave_requests_guard_update() from anon;
revoke all on function public.leave_requests_guard_update() from authenticated;

create trigger leave_requests_guard_update
  before update on public.leave_requests
  for each row
  execute function public.leave_requests_guard_update();
