-- =========================================================
-- Enable RLS
-- =========================================================
alter table public.products  enable row level security;
alter table public.purchases enable row level security;
alter table public.reviews   enable row level security;

-- =========================================================
-- Table privileges (defense in depth alongside RLS)
-- =========================================================
revoke all on public.products  from anon, authenticated;
revoke all on public.purchases from anon, authenticated;
revoke all on public.reviews   from anon, authenticated;

-- R1: products readable by everyone
grant select on public.products to anon, authenticated;

-- R2: purchases readable (own rows via RLS) by signed-in users only; no writes
grant select on public.purchases to authenticated;

-- R1 / R3 / R4: reviews readable by everyone; signed-in users may write
-- only the non-staff columns (is_featured is never writable by users)
grant select on public.reviews to anon, authenticated;
grant insert (product_id, user_id, rating, body) on public.reviews to authenticated;
grant update (product_id, user_id, rating, body) on public.reviews to authenticated;
grant delete on public.reviews to authenticated;

-- R6: service role keeps full access (it also bypasses RLS)
grant all on public.products  to service_role;
grant all on public.purchases to service_role;
grant all on public.reviews   to service_role;

-- =========================================================
-- products policies
-- =========================================================
create policy "products_select_all"
  on public.products
  for select
  to anon, authenticated
  using (true);

-- =========================================================
-- purchases policies
-- =========================================================
create policy "purchases_select_own"
  on public.purchases
  for select
  to authenticated
  using (user_id = (select auth.uid()));
-- No insert/update/delete policies: nobody records purchases through the app.

-- =========================================================
-- reviews policies
-- =========================================================
create policy "reviews_select_all"
  on public.reviews
  for select
  to anon, authenticated
  using (true);

create policy "reviews_insert_own_purchased"
  on public.reviews
  for insert
  to authenticated
  with check (
    user_id = (select auth.uid())
    and is_featured = false
    and exists (
      select 1
      from public.purchases p
      where p.user_id = (select auth.uid())
        and p.product_id = reviews.product_id
    )
  );

create policy "reviews_update_own"
  on public.reviews
  for update
  to authenticated
  using (user_id = (select auth.uid()))
  with check (
    user_id = (select auth.uid())
    and exists (
      select 1
      from public.purchases p
      where p.user_id = (select auth.uid())
        and p.product_id = reviews.product_id
    )
  );

create policy "reviews_delete_own"
  on public.reviews
  for delete
  to authenticated
  using (user_id = (select auth.uid()));

-- =========================================================
-- R4: extra guard so app users can never set/change is_featured
-- =========================================================
create or replace function public.reviews_guard_is_featured()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if current_user in ('anon', 'authenticated') then
    if tg_op = 'INSERT' then
      if new.is_featured is distinct from false then
        raise exception 'is_featured can only be set by staff'
          using errcode = '42501';
      end if;
    elsif tg_op = 'UPDATE' then
      if new.is_featured is distinct from old.is_featured then
        raise exception 'is_featured can only be changed by staff'
          using errcode = '42501';
      end if;
    end if;
  end if;
  return new;
end;
$$;

revoke all on function public.reviews_guard_is_featured() from public, anon, authenticated;

create trigger reviews_guard_is_featured
  before insert or update on public.reviews
  for each row
  execute function public.reviews_guard_is_featured();
