-- Prevent non-service callers from moving a response to another survey/respondent
create or replace function public.survey_responses_lock_keys()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and (new.survey_id is distinct from old.survey_id
          or new.respondent_id is distinct from old.respondent_id) then
    raise exception 'survey_id and respondent_id cannot be changed';
  end if;
  return new;
end;
$$;

