  on public.org_members
  for select
  to authenticated
  using (public.is_org_member(org_id));

-- R2: only admins can see invites of their org
create policy invites_select_admins
  on public.invites
  for select
  to authenticated
  using (public.is_org_admin(org_id));

-- R2: admins create invites naming themselves, unaccepted, expiring in future
create policy invites_insert_admins
  on public.invites
  for insert
  to authenticated
  with check (
    public.is_org_admin(org_id)
    and invited_by = auth.uid()
    and accepted_at is null
    and expires_at > now()
  );

-- R2: admins delete invites of their org
create policy invites_delete_admins
  on public.invites
  for delete
  to authenticated
  using (public.is_org_admin(org_id));

-- R3: accept_invite RPC
create function public.accept_invite(p_token text)
returns bigint
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_uid   uuid := auth.uid();
  v_email text := auth.jwt() ->> 'email';
  v_inv   public.invites%rowtype;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;

  if v_email is null or length(v_email) = 0 then
    raise exception 'no verified email on account' using errcode = '42501';
  end if;

  if p_token is null then
    raise exception 'invalid invite' using errcode = 'P0002';
  end if;

  select * into v_inv
  from public.invites i
  where i.token = p_token
  for update;

  if not found then
    raise exception 'invalid invite' using errcode = 'P0002';
  end if;

  if v_inv.accepted_at is not null then
    raise exception 'invite already accepted' using errcode = '42501';
  end if;

  if v_inv.expires_at <= now() then
    raise exception 'invite expired' using errcode = '42501';
  end if;

  if lower(v_inv.email) <> lower(v_email) then
    raise exception 'invite email does not match' using errcode = '42501';
  end if;

  insert into public.org_members (org_id, user_id, role)
  values (v_inv.org_id, v_uid, v_inv.role)
  on conflict (org_id, user_id) do update set role = excluded.role;

  update public.invites
     set accepted_at = now()
   where token = v_inv.token
     and accepted_at is null;

  return v_inv.org_id;
end;
$$;

