-- Enable RLS on all application tables
alter table public.polls        enable row level security;
alter table public.poll_options enable row level security;
alter table public.votes        enable row level security;

-- ---------------------------------------------------------------------------
-- Grants / revokes
-- ---------------------------------------------------------------------------
-- R6: anonymous visitors get nothing
revoke all on table public.polls        from anon;
revoke all on table public.poll_options from anon;
revoke all on table public.votes        from anon;

-- R1/R5: authenticated users can only read polls and options
revoke all on table public.polls        from authenticated;
revoke all on table public.poll_options from authenticated;
grant select on table public.polls        to authenticated;
grant select on table public.poll_options to authenticated;

-- R2/R3/R4: authenticated users can read/insert/update/delete votes (filtered by RLS)
revoke all on table public.votes from authenticated;
grant select, insert, update, delete on table public.votes to authenticated;

-- R7: service role keeps full access
grant all on table public.polls        to service_role;
grant all on table public.poll_options to service_role;
grant all on table public.votes        to service_role;

-- ---------------------------------------------------------------------------
-- Helper functions
-- ---------------------------------------------------------------------------
create or replace function public.poll_is_open(p_poll_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.polls p
    where p.id = p_poll_id
      and p.closes_at > now()
  );
$$;

create or replace function public.option_belongs_to_poll(p_option_id bigint, p_poll_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.poll_options o
    where o.id = p_option_id
      and o.poll_id = p_poll_id
  );
$$;

revoke all on function public.poll_is_open(bigint) from public, anon;
revoke all on function public.option_belongs_to_poll(bigint, bigint) from public, anon;
grant execute on function public.poll_is_open(bigint) to authenticated, service_role;
grant execute on function public.option_belongs_to_poll(bigint, bigint) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Polls / options: read-only for signed-in users (R1, R5)
-- ---------------------------------------------------------------------------
create policy "polls_select_authenticated"
  on public.polls
  for select
  to authenticated
  using (true);

create policy "poll_options_select_authenticated"
  on public.poll_options
  for select
  to authenticated
  using (true);

-- ---------------------------------------------------------------------------
-- Votes
-- ---------------------------------------------------------------------------
-- R2: users see only their own votes
create policy "votes_select_own"
  on public.votes
  for select
  to authenticated
  using (user_id = (select auth.uid()));

-- R3: vote as yourself, valid option for that poll, poll open
create policy "votes_insert_own_open"
  on public.votes
  for insert
  to authenticated
  with check (
    user_id = (select auth.uid())
    and public.poll_is_open(poll_id)
    and public.option_belongs_to_poll(option_id, poll_id)
  );

-- R4: change own vote while poll is open, only to an option of that poll
create policy "votes_update_own_open"
  on public.votes
  for update
  to authenticated
  using (
    user_id = (select auth.uid())
    and public.poll_is_open(poll_id)
  )
  with check (
    user_id = (select auth.uid())
    and public.poll_is_open(poll_id)
    and public.option_belongs_to_poll(option_id, poll_id)
  );

-- R4: withdraw own vote while poll is open
create policy "votes_delete_own_open"
  on public.votes
  for delete
  to authenticated
  using (
    user_id = (select auth.uid())
    and public.poll_is_open(poll_id)
  );

-- ---------------------------------------------------------------------------
-- Prevent app users from moving a vote to another poll / user on update.
-- (Upsert re-sets poll_id/user_id to identical values, which is allowed.)
-- Service role is exempt (R7).
-- ---------------------------------------------------------------------------
create or replace function public.votes_lock_identity()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if current_user in ('authenticated', 'anon') then
    if new.poll_id is distinct from old.poll_id
       or new.user_id is distinct from old.user_id then
      raise exception 'poll_id and user_id of a vote cannot be changed'
        using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;

create trigger votes_lock_identity
  before update on public.votes
  for each row
  execute function public.votes_lock_identity();
