-- Checks that the current user may decide the given PO.
-- Takes a share lock on the PO row so its amount/requester cannot change
-- concurrently while the decision is being recorded.
create function public.can_decide_po(p_po_id bigint)
returns boolean
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_uid       uuid := auth.uid();
  v_amount    numeric(12, 2);
  v_requester uuid;
  v_limit     numeric(12, 2);
begin
  if v_uid is null then
    return false;
  end if;

  select a.limit_amount into v_limit
  from public.approvers a
  where a.user_id = v_uid;

  if not found then
    return false;
  end if;

  select po.amount, po.requester_id into v_amount, v_requester
  from public.purchase_orders po
  where po.id = p_po_id
  for share;

  if not found then
    return false;
  end if;

  return v_requester <> v_uid and v_amount <= v_limit;
end;
$$;

