-- Race-safe guard for approval inserts.
-- Locks the PO row, then re-checks limit, self-approval and identity against current data.
create function public.po_approvals_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_requester uuid;
  v_amount    numeric(12, 2);
begin
  if auth.role() is distinct from 'authenticated' then
    return new;  -- service role / direct server connections keep full access
  end if;

  select po.requester_id, po.amount
    into v_requester, v_amount
    from public.purchase_orders po
   where po.id = new.po_id
   for update;

  if not found then
    raise exception 'purchase order % not found', new.po_id using errcode = '42501';
  end if;

  if new.approver_id is distinct from auth.uid()
     or v_requester = auth.uid()
     or not exists (
       select 1 from public.approvers a
        where a.user_id = auth.uid() and a.limit_amount >= v_amount
     ) then
    raise exception 'not allowed to decide this purchase order' using errcode = '42501';
  end if;

  return new;
end;
$$;

-- Race-safe guard for PO edits/deletes: blocks once a decision exists (checked after acquiring the row lock)
create function public.purchase_orders_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.role() is distinct from 'authenticated' then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;

  if exists (select 1 from public.po_approvals pa where pa.po_id = old.id) then
    raise exception 'purchase order % is already decided', old.id using errcode = '42501';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

