-- Concurrency guard: lock the PO row and re-check limits at decision time so a
-- concurrent amount edit cannot slip past the approver's limit.
create function public.po_approvals_lock_and_check()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_requester uuid;
  v_amount    numeric(12,2);
  v_limit     numeric(12,2);
begin
  if auth.role() = 'service_role' or current_user in ('postgres', 'service_role', 'supabase_admin') then
    return new;
  end if;

  select po.requester_id, po.amount
    into v_requester, v_amount
  from public.purchase_orders po
  where po.id = new.po_id
  for update;

  select a.limit_amount into v_limit
  from public.approvers a
  where a.user_id = auth.uid();

  if v_requester is null
     or v_limit is null
     or new.approver_id is distinct from auth.uid()
     or v_requester = auth.uid()
     or v_amount > v_limit then
    raise exception 'not permitted to decide this purchase order'
      using errcode = '42501';
  end if;

  return new;
end;
$$;

