create or replace function public.is_approver()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.approvers a where a.user_id = auth.uid()
  );
$$;

create or replace function public.po_is_decided(p_po_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.po_approvals pa where pa.po_id = p_po_id
  );
$$;

create or replace function public.is_po_requester(p_po_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.purchase_orders po
    where po.id = p_po_id
      and po.requester_id = auth.uid()
  );
$$;

-- Volatile so it can lock the PO row, preventing a concurrent
-- requester edit of the amount while a decision is being recorded.
create or replace function public.can_decide_po(p_po_id bigint)
returns boolean
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_amount    numeric(12, 2);
  v_requester uuid;
  v_limit     numeric(12, 2);
begin
  if auth.uid() is null then
    return false;
  end if;

  select a.limit_amount into v_limit
  from public.approvers a
  where a.user_id = auth.uid();

  if v_limit is null then
    return false;
  end if;

  select po.amount, po.requester_id into v_amount, v_requester
  from public.purchase_orders po
  where po.id = p_po_id
  for share;

  if v_amount is null then
    return false;
  end if;

  return v_requester <> auth.uid() and v_amount <= v_limit;
end;
$$;

revoke all on function public.is_approver()            from public, anon;
revoke all on function public.po_is_decided(bigint)    from public, anon;
revoke all on function public.is_po_requester(bigint)  from public, anon;
revoke all on function public.can_decide_po(bigint)    from public, anon;
grant execute on function public.is_approver()           to authenticated;
grant execute on function public.po_is_decided(bigint)  to authenticated;
grant execute on function public.is_po_requester(bigint) to authenticated;
grant execute on function public.can_decide_po(bigint)  to authenticated;

