revoke all on table public.purchase_orders from anon, authenticated;
revoke all on table public.po_approvals    from anon, authenticated;

-- approvers: read only
grant select on table public.approvers to authenticated;

-- purchase_orders: requester_id/id not editable after creation
grant select, delete on table public.purchase_orders to authenticated;
grant insert (requester_id, vendor, amount) on table public.purchase_orders to authenticated;
grant update (vendor, amount) on table public.purchase_orders to authenticated;

-- po_approvals: insert-only, decided_at always takes its default
grant select on table public.po_approvals to authenticated;
grant insert (po_id, approver_id, decision) on table public.po_approvals to authenticated;

grant all on table public.approvers       to service_role;
grant all on table public.purchase_orders to service_role;
grant all on table public.po_approvals    to service_role;

-- =========================================================
-- approvers policies (R5)
-- =========================================================
create policy approvers_select_own
  on public.approvers
  for select
  to authenticated
  using (user_id = auth.uid());

-- =========================================================
-- purchase_orders policies (R1, R2)
-- =========================================================
create policy purchase_orders_select
  on public.purchase_orders
  for select
  to authenticated
  using (requester_id = auth.uid() or public.is_approver());

create policy purchase_orders_insert
  on public.purchase_orders
  for insert
  to authenticated
  with check (requester_id = auth.uid());

create policy purchase_orders_update
  on public.purchase_orders
  for update
  to authenticated
  using (requester_id = auth.uid() and not public.po_is_decided(id))
  with check (requester_id = auth.uid() and not public.po_is_decided(id));

create policy purchase_orders_delete
  on public.purchase_orders
  for delete
  to authenticated
  using (requester_id = auth.uid() and not public.po_is_decided(id));

-- =========================================================
-- po_approvals policies (R3, R4)
-- =========================================================
create policy po_approvals_select
  on public.po_approvals
  for select
  to authenticated
  using (public.is_approver() or public.is_po_requester(po_id));

create policy po_approvals_insert
  on public.po_approvals
  for insert
  to authenticated
  with check (
    approver_id = auth.uid()
    and public.can_decide_po(po_id)
  );

-- No update/delete policies on po_approvals: decisions are immutable.
