as $$
  select coalesce((auth.jwt() -> 'app_metadata' ->> 'role') = 'auditor', false);
$$;

-- Is the current user staff at the given location?
-- SECURITY DEFINER avoids RLS recursion on location_staff.
create or replace function public.is_location_staff(p_location_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.location_staff ls
    where ls.location_id = p_location_id
      and ls.user_id = auth.uid()
  );
