revoke all on public.class_students from anon;
revoke all on public.guardians      from anon;
revoke all on public.grades         from anon;

-- R4: nobody changes classes, enrollments or guardian links through the app
revoke insert, update, delete, truncate on public.classes        from authenticated;
revoke insert, update, delete, truncate on public.class_students from authenticated;
revoke insert, update, delete, truncate on public.guardians      from authenticated;
grant select on public.classes        to authenticated;
grant select on public.class_students to authenticated;
grant select on public.guardians      to authenticated;

-- grades: authenticated may attempt DML; RLS decides
revoke truncate on public.grades from authenticated;
grant select, insert, update, delete on public.grades to authenticated;

-- R6: service role keeps full access (also bypasses RLS)
grant all on public.classes, public.class_students, public.guardians, public.grades to service_role;

