create policy grades_select
  on public.grades
  for select
  to authenticated
  using (
    student_id = (select auth.uid())
    or exists (
      select 1
      from public.guardians g
      where g.guardian_id = (select auth.uid())
        and g.student_id = grades.student_id
    )
    or exists (
      select 1
      from public.classes c
      where c.id = grades.class_id
        and c.teacher_id = (select auth.uid())
    )
  );

