    and exists (
      select 1
      from public.classes c
      where c.id = grades.class_id
        and c.teacher_id = (select auth.uid())
    )
    and exists (
      select 1
      from public.class_students cs
      where cs.class_id = grades.class_id
        and cs.student_id = grades.student_id
    )
  );

