-- Approval RPC
create or replace function public.approve_access(p_request_id bigint)
returns text
language plpgsql
volatile
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_req public.access_requests%rowtype;
  v_count int;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not public.is_ops(v_uid) then
    raise exception 'caller is not on the ops team' using errcode = '42501';
  end if;

  -- Lock the request row to serialize concurrent approvals
  select * into v_req
  from public.access_requests
  where id = p_request_id
  for update;

  if not found then
