-- Helpers: SECURITY DEFINER so they can walk the folder tree without recursive RLS.
-- UNION (not UNION ALL) makes the walk stop if parent_id ever forms a cycle.

create or replace function public.folder_ancestors(fid bigint)
returns table (id bigint)
language sql
stable
security definer
set search_path = ''
as $$
  with recursive anc(id, parent_id) as (
    select f.id, f.parent_id
      from public.folders f
     where f.id = fid
    union
    select p.id, p.parent_id
      from public.folders p
      join anc a on p.id = a.parent_id
  )
  select anc.id from anc;
$$;

create or replace function public.owns_folder_tree(fid bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select auth.uid() is not null and exists (
    select 1
      from public.folder_ancestors(fid) a
      join public.folders f on f.id = a.id
     where f.owner_id = auth.uid()
  );
$$;

create or replace function public.can_read_folder(fid bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select auth.uid() is not null and (
    exists (
      select 1
        from public.folder_ancestors(fid) a
        join public.folders f on f.id = a.id
       where f.owner_id = auth.uid()
    )
    or exists (
      select 1
        from public.folder_ancestors(fid) a
        join public.folder_grants g on g.folder_id = a.id
       where g.user_id = auth.uid()
    )
  );
$$;

create or replace function public.can_edit_folder(fid bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select auth.uid() is not null and (
    exists (
      select 1
        from public.folder_ancestors(fid) a
        join public.folders f on f.id = a.id
       where f.owner_id = auth.uid()
    )
    or exists (
      select 1
        from public.folder_ancestors(fid) a
        join public.folder_grants g on g.folder_id = a.id
       where g.user_id = auth.uid()
         and g.can_edit
    )
  );
$$;

