alter table public.folder_grants enable row level security;
alter table public.documents     enable row level security;

-- Anonymous visitors: no access at all (R5)
revoke all on public.folders       from anon;
revoke all on public.folder_grants from anon;
revoke all on public.documents     from anon;

-- Authenticated table privileges (RLS narrows these)
grant select, insert on public.folders to authenticated;
revoke update, delete, truncate on public.folders from authenticated;
grant select, insert, update, delete on public.folder_grants to authenticated;
grant select, insert, update, delete on public.documents     to authenticated;

-- ===== folders =====
-- R1: read if owner/grantee of the folder or any ancestor
create policy folders_select on public.folders
  for select to authenticated
  using (public.can_read_folder(id));

-- R3: top-level folders as owner; subfolders only under folders owned (directly or via ancestor)
create policy folders_insert on public.folders
  for insert to authenticated
  with check (
    owner_id = auth.uid()
    and (parent_id is null or public.owns_folder_tree(parent_id))
  );

