  for select to authenticated
  using (user_id = auth.uid() or public.owns_folder_tree(folder_id));

-- R3: only owners (directly or via ancestor) add/remove/change grants
create policy folder_grants_insert on public.folder_grants
  for insert to authenticated
  with check (public.owns_folder_tree(folder_id));

create policy folder_grants_update on public.folder_grants
  for update to authenticated
  using (public.owns_folder_tree(folder_id))
  with check (public.owns_folder_tree(folder_id));

create policy folder_grants_delete on public.folder_grants
  for delete to authenticated
  using (public.owns_folder_tree(folder_id));

-- ===== documents =====
-- R1: read documents in readable folders
create policy documents_select on public.documents
  for select to authenticated
  using (public.can_read_folder(folder_id));

-- R2: create/edit/delete where user can edit; moves only into editable folders
create policy documents_insert on public.documents
  for insert to authenticated
  with check (public.can_edit_folder(folder_id));

create policy documents_update on public.documents
  for update to authenticated
  using (public.can_edit_folder(folder_id))
  with check (public.can_edit_folder(folder_id));

create policy documents_delete on public.documents
  for delete to authenticated
  using (public.can_edit_folder(folder_id));
