revoke all on table public.ops_team from anon, authenticated;
revoke all on table public.access_requests from anon, authenticated;
revoke all on table public.access_approvals from anon, authenticated;

grant select on table public.ops_team to authenticated;
grant select, insert, delete on table public.access_requests to authenticated;
grant select on table public.access_approvals to authenticated;

grant all on table public.ops_team to service_role;
grant all on table public.access_requests to service_role;
grant all on table public.access_approvals to service_role;

-- Helper: is the caller on the ops team?
create or replace function public.is_ops_member()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.ops_team o where o.user_id = auth.uid()
  );
$$;

revoke all on function public.is_ops_member() from public, anon;
grant execute on function public.is_ops_member() to authenticated, service_role;

-- ops_team: signed-in users can see who is on the team (R1)
create policy ops_team_select_authenticated
  on public.ops_team
  for select
  to authenticated
  using (true);

-- access_requests: requesters see own, ops see all (R1)
create policy access_requests_select
  on public.access_requests
  for select
  to authenticated
  using (requester_id = auth.uid() or public.is_ops_member());

-- access_requests: create as self, always pending (R2)
create policy access_requests_insert_own_pending
  on public.access_requests
  for insert
  to authenticated
  with check (requester_id = auth.uid() and status = 'pending');

-- access_requests: withdraw own pending requests (R2)
create policy access_requests_delete_own_pending
  on public.access_requests
  for delete
  to authenticated
  using (requester_id = auth.uid() and status = 'pending');

-- access_approvals: visible to requester of the request, and to ops (R1)
create policy access_approvals_select
  on public.access_approvals
  for select
  to authenticated
  using (
    public.is_ops_member()
    or exists (
      select 1 from public.access_requests r
      where r.id = access_approvals.request_id
        and r.requester_id = auth.uid()
    )
  );

-- approve_access RPC (R4)
create or replace function public.approve_access(p_request_id bigint)
returns text
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_req public.access_requests%rowtype;
  v_count integer;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not exists (select 1 from public.ops_team o where o.user_id = v_uid) then
    raise exception 'caller is not on the ops team' using errcode = '42501';
  end if;

  -- Lock the request row to serialize concurrent approvals
  select * into v_req
  from public.access_requests r
  where r.id = p_request_id
  for update;

  if not found then
    raise exception 'request % does not exist', p_request_id using errcode = 'P0002';
  end if;

  if v_req.status <> 'pending' then
    raise exception 'request % is not pending', p_request_id using errcode = 'P0001';
  end if;

  if v_req.requester_id = v_uid then
    raise exception 'cannot approve your own request' using errcode = '42501';
  end if;

  if exists (
    select 1 from public.access_approvals a
    where a.request_id = p_request_id and a.approver_id = v_uid
  ) then
    raise exception 'you have already approved request %', p_request_id using errcode = 'P0001';
  end if;

  insert into public.access_approvals (request_id, approver_id, approved_at)
  values (p_request_id, v_uid, now());

  select count(distinct a.approver_id) into v_count
  from public.access_approvals a
  join public.ops_team o on o.user_id = a.approver_id
  where a.request_id = p_request_id
    and a.approver_id <> v_req.requester_id;

  if v_count >= 2 then
    update public.access_requests
       set status = 'granted'
     where id = p_request_id;
    return 'granted';
  end if;

  return v_req.status;
end;
$$;

revoke all on function public.approve_access(bigint) from public, anon;
grant execute on function public.approve_access(bigint) to authenticated, service_role;
