    booked_by is null
    and starts_at > now()
  );

-- R5 defense in depth: block changes to anything other than booked_by
-- for non-service roles, even if grants are later widened.
create or replace function public.slots_guard_immutable_columns()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if auth.role() = 'service_role' or current_user in ('postgres', 'service_role', 'supabase_admin') then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.provider_id is distinct from old.provider_id
     or new.starts_at is distinct from old.starts_at then
    raise exception 'Only booked_by may be changed on slots';
  end if;

  return new;
end;
$$;

