  using (
    (select public.is_pharmacist())
    or exists (
      select 1 from public.prescriptions pr
      where pr.id = dispenses.prescription_id
        and pr.patient_id = (select auth.uid())
    )
  );

-- =========================================================
-- RPC: dispense
-- =========================================================
create or replace function public.dispense(p_prescription_id bigint)
returns integer
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_uid     uuid := auth.uid();
  v_rx      public.prescriptions%rowtype;
  v_left    integer;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if not exists (select 1 from public.pharmacists p where p.user_id = v_uid) then
    raise exception 'caller is not a pharmacist' using errcode = '42501';
  end if;

  -- lock the prescription row to serialize concurrent dispenses
  select * into v_rx
  from public.prescriptions
  where id = p_prescription_id
  for update;

  if not found then
    raise exception 'prescription not found' using errcode = 'P0002';
  end if;

  if v_rx.patient_id = v_uid then
    raise exception 'cannot dispense own prescription' using errcode = '42501';
  end if;

  if v_rx.expires_at <= now() then
    raise exception 'prescription has expired' using errcode = 'P0001';
  end if;

  if v_rx.refills_left <= 0 then
    raise exception 'no refills left' using errcode = 'P0001';
  end if;

  update public.prescriptions
     set refills_left = refills_left - 1
   where id = p_prescription_id
     and refills_left > 0
  returning refills_left into v_left;

  if not found then
    raise exception 'no refills left' using errcode = 'P0001';
  end if;

  insert into public.dispenses (prescription_id, pharmacist_id, dispensed_at)
  values (p_prescription_id, v_uid, now());

  return v_left;
end;
$$;

