returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_amr jsonb;
begin
  v_amr := auth.jwt() -> 'amr';
  if v_amr is null or jsonb_typeof(v_amr) <> 'array' then
    return false;
  end if;
  return exists (
    select 1
    from jsonb_array_elements(v_amr) as e(elem)
    where jsonb_typeof(e.elem) = 'object'
      and e.elem ->> 'method' = 'sso/saml'
  );
end;
$$;

