-- R3: checkout
create or replace function public.checkout_document(p_doc_id bigint)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_count integer;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  update public.documents d
     set checked_out_by = v_uid
   where d.id = p_doc_id
     and (d.checked_out_by is null or d.checked_out_by = v_uid)
     and exists (
       select 1
       from public.doc_access a
       where a.doc_id = d.id
         and a.user_id = v_uid
         and a.can_edit
     );

  get diagnostics v_count = row_count;
  if v_count <> 1 then
    raise exception 'cannot check out document %', p_doc_id using errcode = '42501';
  end if;
end;
$$;

-- R4: checkin
create or replace function public.checkin_document(p_doc_id bigint, p_body text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_count integer;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if p_body is null then
    raise exception 'body must not be null' using errcode = '22004';
  end if;

  update public.documents d
     set body = p_body,
         checked_out_by = null
   where d.id = p_doc_id
     and d.checked_out_by = v_uid;

  get diagnostics v_count = row_count;
  if v_count <> 1 then
    raise exception 'document % is not checked out by caller', p_doc_id using errcode = '42501';
  end if;
end;
$$;

