-- R3: check out a document
create or replace function public.checkout_document(p_doc_id bigint)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_holder uuid;
  v_can_edit boolean;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select d.checked_out_by
    into v_holder
    from public.documents d
   where d.id = p_doc_id
   for update;

  if not found then
    raise exception 'document not found or no edit access' using errcode = '42501';
  end if;

  select da.can_edit
    into v_can_edit
    from public.doc_access da
   where da.doc_id = p_doc_id
     and da.user_id = v_uid;

  if v_can_edit is not true then
    raise exception 'document not found or no edit access' using errcode = '42501';
  end if;

  if v_holder is not null and v_holder <> v_uid then
    raise exception 'document is checked out by another user' using errcode = '55P03';
  end if;

  update public.documents
     set checked_out_by = v_uid
   where id = p_doc_id;
end;
$$;

-- R4: save body and release the lock
create or replace function public.checkin_document(p_doc_id bigint, p_body text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_holder uuid;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select d.checked_out_by
    into v_holder
    from public.documents d
   where d.id = p_doc_id
   for update;

  if not found or v_holder is distinct from v_uid then
    raise exception 'document is not checked out by you' using errcode = '42501';
  end if;

  if p_body is null then
    raise exception 'body must not be null' using errcode = '22004';
  end if;

  update public.documents
     set body = p_body,
         checked_out_by = null
   where id = p_doc_id;
end;
$$;

