-- R3: check out a document
create or replace function public.checkout_document(p_doc_id bigint)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_holder uuid;
  v_found boolean;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select d.checked_out_by, true
    into v_holder, v_found
    from public.documents d
   where d.id = p_doc_id
   for update;

  if not coalesce(v_found, false) then
    raise exception 'document % not found', p_doc_id using errcode = 'P0002';
  end if;

  if not exists (
    select 1
      from public.doc_access da
     where da.doc_id = p_doc_id
       and da.user_id = v_uid
       and da.can_edit
  ) then
    raise exception 'no edit access to document %', p_doc_id using errcode = '42501';
  end if;

  if v_holder is not null and v_holder <> v_uid then
    raise exception 'document % is checked out by another user', p_doc_id using errcode = '55P03';
  end if;

  update public.documents
     set checked_out_by = v_uid
   where id = p_doc_id;
end;
$$;

