  end if;

  select d.checked_out_by, true
    into v_holder, v_found
    from public.documents d
   where d.id = p_doc_id
   for update;

  if not coalesce(v_found, false) or v_holder is null or v_holder <> v_uid then
    raise exception 'document % is not checked out by you', p_doc_id using errcode = '42501';
  end if;

  if p_body is null then
    raise exception 'body must not be null' using errcode = '22004';
  end if;

  update public.documents
     set body = p_body,
         checked_out_by = null
   where id = p_doc_id;
end;
$$;

