-- R1: signed-in users can read only their own usage rows.
create policy "api_usage_select_own"
  on public.api_usage
  for select
  to authenticated
  using ((select auth.uid()) = user_id);

-- R3: there are no insert, update or delete policies, so app roles cannot change data.
-- Remove the table privileges as well, as a second layer of protection.
revoke all on table public.api_usage from public;
revoke all on table public.api_usage from anon;
revoke all on table public.api_usage from authenticated;
grant select on table public.api_usage to authenticated;

-- R5: the service role keeps full access (it also bypasses RLS).
grant select, insert, update, delete on table public.api_usage to service_role;

-- R2: summary view, one row per user.
-- security_invoker makes the base table's RLS apply for the caller.
-- Authenticated users see only their own row.
-- service_role bypasses RLS and sees every user.
create view public.usage_summary
  with (security_invoker = true)
as
select
  u.user_id,
  sum(u.requests)::bigint as total_requests,
  count(*) filter (where u.requests > 0)::bigint as active_days
from public.api_usage u
group by u.user_id;

-- R4: anonymous visitors get nothing. R3: the view is read-only for app roles.
revoke all on table public.usage_summary from public;
revoke all on table public.usage_summary from anon;
revoke all on table public.usage_summary from authenticated;
grant select on table public.usage_summary to authenticated;
grant select on table public.usage_summary to service_role;
