grant all on table public.api_usage to service_role;

-- R1: signed-in users read only their own rows (no write policies => R3)
create policy "api_usage_select_own"
  on public.api_usage
  for select
  to authenticated
  using (user_id = (select auth.uid()));

-- R2: summary view that runs with the caller's privileges, so base-table RLS applies.
-- The service role bypasses RLS and sees every user (R5).
create view public.usage_summary
  with (security_invoker = true)
as
select
  u.user_id,
  sum(u.requests)::bigint                         as total_requests,
  count(*) filter (where u.requests > 0)::bigint  as active_days
from public.api_usage u
