```sql
-- =========================================================
-- Enable RLS
-- =========================================================
alter table public.items  enable row level security;
alter table public.claims enable row level security;

-- =========================================================
-- Grants (R5: anon gets nothing; authenticated limited columns)
-- =========================================================
revoke all on public.items  from anon;
revoke all on public.claims from anon;
revoke all on public.items  from authenticated;
revoke all on public.claims from authenticated;

grant select, insert, delete on public.items to authenticated;
grant update (description, status) on public.items to authenticated;

grant select on public.claims to authenticated;
grant insert (item_id, claimant_id, message, status) on public.claims to authenticated;
grant update (status) on public.claims to authenticated;

grant all on public.items  to service_role;
grant all on public.claims to service_role;

-- =========================================================
-- ITEMS policies (R1)
-- =========================================================
create policy items_select_authenticated
  on public.items for select
  to authenticated
  using (true);

create policy items_insert_own_open
  on public.items for insert
  to authenticated
  with check (
    found_by = (select auth.uid())
    and status = 'open'
  );

create policy items_update_own
  on public.items for update
  to authenticated
  using (found_by = (select auth.uid()))
  with check (found_by = (select auth.uid()));

create policy items_delete_own
  on public.items for delete
  to authenticated
  using (found_by = (select auth.uid()));

-- =========================================================
-- CLAIMS policies (R2, R3, R4)
-- =========================================================
create policy claims_select_claimant_or_finder
  on public.claims for select
  to authenticated
  using (
    claimant_id = (select auth.uid())
    or exists (
      select 1 from public.items i
      where i.id = claims.item_id
        and i.found_by = (select auth.uid())
    )
  );

create policy claims_insert_as_self_pending
  on public.claims for insert
  to authenticated
  with check (
    claimant_id = (select auth.uid())
    and status = 'pending'
    and exists (
      select 1 from public.items i
      where i.id = claims.item_id
        and i.status = 'open'
        and i.found_by <> (select auth.uid())
    )
  );

create policy claims_update_finder_decides_pending
  on public.claims for update
  to authenticated
  using (
    status = 'pending'
    and exists (
      select 1 from public.items i
      where i.id = claims.item_id
        and i.found_by = (select auth.uid())
    )
  )
  with check (
    status in ('approved', 'rejected')
    and exists (
      select 1 from public.items i
      where i.id = claims.item_id
        and i.found_by = (select auth.uid())
    )
  );

-- =========================================================
-- Trigger: immutability + single approved claim per item
-- =========================================================
create or replace function public.claims_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  is_service boolean := coalesce(auth.role(), '') = 'service_role'
                        or current_user in ('postgres', 'service_role', 'supabase_admin');
begin
  if tg_op = 'UPDATE' and not is_service then
    if new.id          is distinct from old.id
       or new.item_id     is distinct from old.item_id
       or new.claimant_id is distinct from old.claimant_id
       or new.message     is distinct from old.message then
      raise exception 'Only the status of a claim may change';
    end if;
    if old.status <> 'pending' then
      raise exception 'Only pending claims can be decided';
    end if;
    if new.status not in ('approved', 'rejected') then
      raise exception 'A pending claim can only be approved or rejected';
    end if;
  end if;

  if new.status = 'approved' then
    -- serialize approvals per item
    perform 1 from public.items where id = new.item_id for update;
    if exists (
      select 1 from public.claims c
      where c.item_id = new.item_id
        and c.status = 'approved'
        and c.id <> new.id
    ) then
      raise exception 'Item already has an approved claim';
    end if;
  end if;

  return new;
end;
$$;

revoke all on function public.claims_guard() from public, anon, authenticated;

create trigger claims_guard_trg
  before insert or update on public.claims
  for each row execute function public.claims_guard();
