        where i.id = new.item_id and i.found_by = auth.uid()
      ) then
        raise exception 'Only the finder can decide on a claim';
      end if;
    end if;
  end if;

  if new.status = 'approved'
     and (tg_op = 'INSERT' or old.status is distinct from 'approved'
          or new.item_id is distinct from old.item_id) then
    -- serialize approvals per item
    perform 1 from public.items i where i.id = new.item_id for update;
    if exists (
      select 1 from public.claims c
      where c.item_id = new.item_id
        and c.status = 'approved'
        and c.id <> new.id
    ) then
      raise exception 'Item already has an approved claim';
    end if;
  end if;

  return new;
end;
$$;

