set search_path = ''
as $$
declare
  v_order public.orders%rowtype;
  v_uid uuid := auth.uid();
begin
  select * into v_order
  from public.orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'order % not found', p_order_id;
  end if;

  if v_uid is null or v_order.buyer_id is distinct from v_uid then
    raise exception 'not authorized to release funds for order %', p_order_id;
  end if;

  if v_order.status <> 'shipped' then
    raise exception 'order % cannot be released from status %', p_order_id, v_order.status;
  end if;

  update public.orders
     set status = 'released'
   where id = p_order_id;

  return 'released';
end;
$$;

