returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order public.orders%rowtype;
  v_uid uuid := auth.uid();
begin
  select * into v_order
  from public.orders
  where id = p_order_id
  for update;

  if not found then
    raise exception 'order % not found', p_order_id;
  end if;

  if v_uid is null or v_order.seller_id is distinct from v_uid then
    raise exception 'not authorized to refund order %', p_order_id;
  end if;

  if v_order.status not in ('paid', 'shipped') then
