  -- R4: reviewed segments are frozen
  if old.status = 'reviewed' then
    raise exception 'Reviewed segments cannot be modified';
  end if;

  -- R4: immutable identity / source columns
  if new.id is distinct from old.id
     or new.project_id is distinct from old.project_id
     or new.lang is distinct from old.lang
     or new.source_text is distinct from old.source_text then
    raise exception 'id, project_id, lang and source_text cannot be changed';
  end if;

  v_is_reviewer   := public.has_lang_role(old.project_id, old.lang, 'reviewer');
  v_is_translator := public.has_lang_role(old.project_id, old.lang, 'translator');

  if not (v_is_reviewer or v_is_translator) then
    raise exception 'Not assigned to this segment language';
  end if;

  -- R3: only reviewers may change status, and only draft -> reviewed
  if new.status is distinct from old.status then
    if not v_is_reviewer then
      raise exception 'Only reviewers can change segment status';
    end if;
    if not (old.status = 'draft' and new.status = 'reviewed') then
      raise exception 'Invalid status transition';
    end if;
  end if;

  -- R2: translators must record themselves when editing
  if not v_is_reviewer then
    if new.translated_by is distinct from auth.uid() then
      raise exception 'translated_by must be the current user';
    end if;
  end if;

  -- Nobody may attribute a translation to someone else
  if new.translated_by is distinct from old.translated_by
     and new.translated_by is distinct from auth.uid() then
    raise exception 'translated_by can only be set to the current user';
  end if;

  return new;
end;
$$;

