returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  -- Only constrain app-facing roles; service_role / postgres keep full access
  if current_user not in ('authenticated', 'anon') then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  -- R4: approved chores are immutable
  if old.status = 'approved' then
    raise exception 'approved chores cannot be changed or deleted';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  if new.id is distinct from old.id then
    raise exception 'chore id cannot be changed';
  end if;

  -- R3: non-parents (children) may only flip status todo -> done
  if not public.is_household_parent(old.household_id) then
    if new.household_id is distinct from old.household_id
       or new.title is distinct from old.title
       or new.assignee_id is distinct from old.assignee_id
       or new.points is distinct from old.points then
      raise exception 'children may only change the status of a chore';
    end if;
    if not (old.status = 'todo' and new.status = 'done') then
      raise exception 'children may only mark todo chores as done';
    end if;
  end if;

  return new;
end;
$$;

