  if new.id is distinct from old.id
     or new.household_id is distinct from old.household_id then
    raise exception 'Chore id and household cannot be changed';
  end if;

  if public.is_household_parent(old.household_id) then
    -- Parents: may edit; approval only from done
    if new.status = 'approved' and old.status <> 'done' then
      raise exception 'Only done chores can be approved';
    end if;
    return new;
  end if;

  -- Children (or anyone else): only todo -> done on own chore, nothing else
  if old.assignee_id is distinct from auth.uid()
     or new.assignee_id is distinct from old.assignee_id
     or new.title       is distinct from old.title
     or new.points      is distinct from old.points
     or old.status <> 'todo'
     or new.status <> 'done' then
    raise exception 'Children may only mark their own todo chores as done';
  end if;

  return new;
end;
$$;

