grant all on table public.bids to service_role;

-- R1: signed-in users can see every auction
create policy auctions_select_authenticated
  on public.auctions
  for select
  to authenticated
  using (true);

-- R1: bidders see their own bids; sellers see all bids on their auctions
create policy bids_select_own_or_seller
  on public.bids
  for select
  to authenticated
  using (
    bidder_id = (select auth.uid())
    or exists (
      select 1
      from public.auctions a
      where a.id = bids.auction_id
        and a.seller_id = (select auth.uid())
    )
  );

-- R3/R4: place_bid RPC
create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid     uuid := auth.uid();
  v_auction public.auctions%rowtype;
  v_amount  numeric(10, 2);
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;

  if p_auction_id is null then
    raise exception 'auction not found' using errcode = 'P0002';
  end if;

  if p_amount is null or p_amount = 'NaN'::numeric then
    raise exception 'invalid amount' using errcode = '22023';
  end if;

  -- Normalize to stored precision before comparing
  v_amount := p_amount::numeric(10, 2);

  -- Lock the auction row to serialize concurrent bids
  select * into v_auction
  from public.auctions
  where id = p_auction_id
  for update;

  if not found then
    raise exception 'auction not found' using errcode = 'P0002';
  end if;

  if v_auction.ends_at <= now() then
    raise exception 'auction has ended' using errcode = 'P0001';
  end if;

  if v_auction.seller_id = v_uid then
    raise exception 'sellers cannot bid on their own auction' using errcode = '42501';
  end if;

  if v_auction.highest_bid is null then
    if v_amount < v_auction.starting_price then
      raise exception 'bid must be at least the starting price (%)', v_auction.starting_price
        using errcode = 'P0001';
    end if;
  else
    if v_amount < v_auction.highest_bid + v_auction.min_increment then
      raise exception 'bid must be at least % ', v_auction.highest_bid + v_auction.min_increment
        using errcode = 'P0001';
    end if;
  end if;

  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, v_uid, v_amount, now());

  update public.auctions
     set highest_bid = v_amount,
         highest_bidder = v_uid
   where id = p_auction_id;

  return v_amount;
end;
$$;

revoke all on function public.place_bid(bigint, numeric) from public;
revoke all on function public.place_bid(bigint, numeric) from anon;
grant execute on function public.place_bid(bigint, numeric) to authenticated;
grant execute on function public.place_bid(bigint, numeric) to service_role;
