-- Enable RLS on the emails table
alter table public.emails enable row level security;

-- R4: anonymous visitors get no table privileges at all
revoke all on table public.emails from anon;

-- Authenticated users: restrict privileges at the column level so that
-- they can never write id or sent_at directly (R3), in addition to RLS.
revoke all on table public.emails from authenticated;
grant select, delete on table public.emails to authenticated;
grant insert (user_id, to_address, subject, body) on table public.emails to authenticated;
grant update (to_address, subject, body) on table public.emails to authenticated;

-- R5: the service role keeps full access (it also bypasses RLS)
grant all on table public.emails to service_role;

-- R1: users can read their own emails, both drafts and sent ones
create policy "emails_select_own"
  on public.emails
  for select
  to authenticated
  using (user_id = (select auth.uid()));

-- R2/R3: users can create drafts only, as themselves, with no sent_at
create policy "emails_insert_own_draft"
  on public.emails
  for insert
  to authenticated
  with check (
    user_id = (select auth.uid())
    and sent_at is null
  );

-- R2/R3: users can edit only their own unsent drafts,
-- and the row must remain an unsent draft they own
create policy "emails_update_own_draft"
  on public.emails
  for update
  to authenticated
  using (
    user_id = (select auth.uid())
    and sent_at is null
  )
  with check (
    user_id = (select auth.uid())
    and sent_at is null
  );

-- R2/R3: users can delete only their own unsent drafts
create policy "emails_delete_own_draft"
  on public.emails
  for delete
  to authenticated
  using (
    user_id = (select auth.uid())
    and sent_at is null
  );
