-- Enable RLS on both tables
alter table public.events   enable row level security;
alter table public.checkins enable row level security;

-- R4: anonymous visitors get no table privileges at all
revoke all on table public.events   from anon;
revoke all on table public.checkins from anon;

-- Reset authenticated privileges, then grant only what the app needs
revoke all on table public.events   from authenticated;
revoke all on table public.checkins from authenticated;

-- R1: signed-in users can read events
grant select on table public.events to authenticated;

-- R1 + R2 + R3: users can read check-ins and insert only event_id and user_id.
-- checked_in_at can never be supplied, so it always takes default now().
-- No update or delete privileges, so check-ins cannot be changed or removed.
grant select on table public.checkins to authenticated;
grant insert (event_id, user_id) on table public.checkins to authenticated;

-- R5: the service role keeps full access (it also bypasses RLS)
grant all on table public.events   to service_role;
grant all on table public.checkins to service_role;

-- R1: every signed-in user can see every event
create policy "events_select_authenticated"
  on public.events
  for select
  to authenticated
  using (true);

-- R1: users see only their own check-ins
-- (this also lets insert(...).select() return the new row)
create policy "checkins_select_own"
  on public.checkins
  for select
  to authenticated
  using (user_id = (select auth.uid()));

-- R2: users check in only themselves, only while the event is live.
-- "Once per event" is enforced by the (event_id, user_id) primary key.
create policy "checkins_insert_self_live_event"
  on public.checkins
  for insert
  to authenticated
  with check (
    user_id = (select auth.uid())
    and exists (
      select 1
      from public.events e
      where e.id = checkins.event_id
        and now() >= e.starts_at
        and now() <= e.ends_at
    )
  );
