-- Trigger enforcing allowed state transitions and immutable fields
create or replace function public.jobs_enforce_update_rules()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_is_customer boolean;
  v_is_mechanic boolean;
begin
  -- Only enforce for app roles; service_role / postgres keep full access
  if current_user not in ('anon', 'authenticated') then
    return new;
  end if;

  if v_uid is null then
    raise exception 'not allowed';
  end if;

  -- Identity fields are never changeable from the app
  if new.id is distinct from old.id
     or new.garage_id is distinct from old.garage_id
     or new.customer_id is distinct from old.customer_id then
    raise exception 'job identity fields cannot be changed';
  end if;

  v_is_customer := (old.customer_id = v_uid);
  v_is_mechanic := public.is_garage_mechanic(old.garage_id);

  -- R3: customer approves a quoted job; nothing else may change
  if v_is_customer
     and old.status = 'quoted'
     and new.status = 'approved'
     and new.vehicle is not distinct from old.vehicle
     and new.quote_amount is not distinct from old.quote_amount then
    return new;
  end if;

  if v_is_mechanic then
    -- R2: mechanics may edit the quote while the job remains quoted
    if old.status = 'quoted' and new.status = 'quoted' then
      return new;
    end if;

    -- R4: approved -> in_progress -> done, nothing else changes
    if ((old.status = 'approved' and new.status = 'in_progress')
        or (old.status = 'in_progress' and new.status = 'done'))
       and new.vehicle is not distinct from old.vehicle
       and new.quote_amount is not distinct from old.quote_amount then
      return new;
    end if;
  end if;

  raise exception 'job update not allowed';
end;
$$;

