-- Transition / immutability enforcement for job updates
-- =========================================================
create or replace function public.jobs_enforce_update()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_is_customer boolean;
  v_is_mechanic boolean;
begin
  -- Server-side / privileged roles keep full access.
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  -- Identity columns are always immutable for app users.
  if new.id is distinct from old.id
     or new.garage_id is distinct from old.garage_id
     or new.customer_id is distinct from old.customer_id then
    raise exception 'job id, garage and customer cannot be changed';
  end if;

  v_is_customer := (old.customer_id = v_uid);
  v_is_mechanic := public.is_garage_mechanic(old.garage_id);

  -- Mechanic editing a quote while still quoted.
  if old.status = 'quoted' and new.status = 'quoted' then
    if v_is_mechanic then
      return new;
    end if;
    if new.vehicle is distinct from old.vehicle
       or new.quote_amount is distinct from old.quote_amount then
      raise exception 'only mechanics can change a quote';
    end if;
    return new;
  end if;

  -- Customer approving a quote: nothing else may change.
  if old.status = 'quoted' and new.status = 'approved' then
    if not v_is_customer then
      raise exception 'only the job''s customer can approve a quote';
    end if;
    if new.vehicle is distinct from old.vehicle
       or new.quote_amount is distinct from old.quote_amount then
      raise exception 'approving cannot change the job';
    end if;
    return new;
  end if;

  -- Mechanic progressing work: approved -> in_progress -> done.
  if (old.status = 'approved' and new.status = 'in_progress')
     or (old.status = 'in_progress' and new.status = 'done') then
    if not v_is_mechanic then
      raise exception 'only garage mechanics can progress a job';
    end if;
    if new.vehicle is distinct from old.vehicle
       or new.quote_amount is distinct from old.quote_amount then
      raise exception 'quote cannot change after approval';
    end if;
    return new;
  end if;

  -- Same non-quoted status: allow only true no-op updates.
  if old.status = new.status then
    if new.vehicle is distinct from old.vehicle
       or new.quote_amount is distinct from old.quote_amount then
      raise exception 'job cannot be changed in status %', old.status;
    end if;
    return new;
  end if;

  raise exception 'invalid status transition % -> %', old.status, new.status;
end;
$$;

