  on public.mechanics
  for select
  to authenticated
  using (user_id = (select auth.uid()));

-- jobs: customers see their own; mechanics see their garage's jobs
create policy jobs_select_customer_or_mechanic
  on public.jobs
  for select
  to authenticated
  using (
    customer_id = (select auth.uid())
    or public.is_garage_mechanic(garage_id)
  );

-- jobs: mechanics open jobs for their garage, always 'quoted'
create policy jobs_insert_mechanic
  on public.jobs
  for insert
  to authenticated
  with check (
    status = 'quoted'
    and public.is_garage_mechanic(garage_id)
  );

-- jobs: customers and garage mechanics may attempt updates;
-- the trigger below enforces exactly which transitions are allowed.
create policy jobs_update_customer_or_mechanic
  on public.jobs
  for update
  to authenticated
  using (
    customer_id = (select auth.uid())
    or public.is_garage_mechanic(garage_id)
  )
  with check (
    customer_id = (select auth.uid())
    or public.is_garage_mechanic(garage_id)
  );

-- No delete policy: jobs are never deleted by app users.

-- Transition enforcement for jobs updates
create or replace function public.jobs_enforce_update()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_is_customer boolean;
  v_is_mechanic boolean;
begin
  -- Only constrain app roles; service role / server-side keeps full access.
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  if v_uid is null then
    raise exception 'not allowed';
  end if;

  v_is_customer := (old.customer_id = v_uid);
  v_is_mechanic := public.is_garage_mechanic(old.garage_id);

  -- Identity columns are immutable for app users
  if new.id is distinct from old.id
     or new.garage_id is distinct from old.garage_id
     or new.customer_id is distinct from old.customer_id then
    raise exception 'job ownership fields cannot be changed';
  end if;

  -- Mechanic edits a quote while still quoted
  if old.status = 'quoted' and new.status = 'quoted' then
    if v_is_mechanic then
      return new;
    end if;
    raise exception 'only garage mechanics can change a quote';
  end if;

  -- Customer approves a quoted job; nothing else may change
  if old.status = 'quoted' and new.status = 'approved' then
    if v_is_customer
       and new.vehicle is not distinct from old.vehicle
       and new.quote_amount is not distinct from old.quote_amount then
      return new;
    end if;
    raise exception 'only the customer can approve, without other changes';
  end if;

  -- Mechanic progresses work; quote and details unchanged
  if (old.status = 'approved' and new.status = 'in_progress')
     or (old.status = 'in_progress' and new.status = 'done') then
    if v_is_mechanic
       and new.vehicle is not distinct from old.vehicle
       and new.quote_amount is not distinct from old.quote_amount then
      return new;
    end if;
    raise exception 'only garage mechanics can progress a job, without other changes';
  end if;

  raise exception 'invalid job update from % to %', old.status, new.status;
end;
$$;

create trigger jobs_enforce_update
  before update on public.jobs
  for each row
  execute function public.jobs_enforce_update();
