-- =========================================================
create function public.jobs_enforce_update()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_uid     uuid := auth.uid();
  v_is_cust boolean;
  v_is_mech boolean;
begin
  -- Service role / server-side roles keep full access.
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;

  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  -- Identity columns of a job can never change through the app.
  if new.id is distinct from old.id
     or new.garage_id is distinct from old.garage_id
     or new.customer_id is distinct from old.customer_id then
    raise exception 'job id, garage and customer cannot be changed';
  end if;

  v_is_cust := (old.customer_id = v_uid);
  v_is_mech := public.is_garage_mechanic(old.garage_id);

  -- Approval: only the customer, only from quoted, nothing else changes.
  if new.status = 'approved' and old.status is distinct from 'approved' then
    if old.status <> 'quoted' then
      raise exception 'only quoted jobs can be approved';
    end if;
    if not v_is_cust then
      raise exception 'only the customer can approve a job';
    end if;
    if new.vehicle is distinct from old.vehicle
       or new.quote_amount is distinct from old.quote_amount then
      raise exception 'approving cannot change the job';
    end if;
    return new;
  end if;

  if v_is_mech then
    -- Editing a quote while still quoted.
    if old.status = 'quoted' and new.status = 'quoted' then
      return new;
    end if;

    -- After approval the quote and vehicle are frozen.
    if new.vehicle is distinct from old.vehicle
       or new.quote_amount is distinct from old.quote_amount then
      raise exception 'job details cannot change after approval';
    end if;

    if (old.status = 'approved'    and new.status = 'in_progress')
       or (old.status = 'in_progress' and new.status = 'done')
       or (old.status = new.status) then
      return new;
    end if;

    raise exception 'invalid status transition from % to %', old.status, new.status;
  end if;

  raise exception 'not allowed to update this job';
end;
$$;

