    if new.published_at is not null then
      raise exception 'drafts cannot have published_at';
    end if;
    return new;
  end if;

  -- UPDATE
  if new.id is distinct from old.id then
    raise exception 'id cannot be changed';
  end if;
  if new.author_id is distinct from old.author_id then
    raise exception 'author cannot be changed';
  end if;

  if old.status = 'published' then
    raise exception 'published articles cannot be changed';

  elsif old.status = 'draft' then
    if v_uid is null or old.author_id <> v_uid then
      raise exception 'only the author can edit a draft';
    end if;
    if new.status not in ('draft', 'in_review') then
      raise exception 'writers cannot publish';
    end if;
    if new.published_at is not null then
      raise exception 'unpublished articles cannot have published_at';
    end if;

  elsif old.status = 'in_review' then
    if not v_is_editor then
      raise exception 'only editors can edit articles in review';
    end if;
    if new.status not in ('draft', 'in_review', 'published') then
      raise exception 'invalid status';
    end if;
    if new.status <> 'published' and new.published_at is not null then
      raise exception 'unpublished articles cannot have published_at';
    end if;
  end if;

  return new;
end;
$$;

