create or replace function public.redeem_referral(p_code text)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_caller   uuid := auth.uid();
  v_owner    uuid;
  v_count    integer;
  v_id       bigint;
begin
  if v_caller is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if p_code is null then
    raise exception 'referral code not found' using errcode = 'P0002';
  end if;

  -- Serialize all redemptions to prevent races on the
  -- "already redeemed" and "max 5 referrals" checks.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('public.redeem_referral'));

  select rc.user_id
    into v_owner
    from public.referral_codes rc
   where rc.code = p_code
   for share;

  if v_owner is null then
    raise exception 'referral code not found' using errcode = 'P0002';
  end if;

  if v_owner = v_caller then
    raise exception 'cannot redeem your own referral code' using errcode = 'P0001';
  end if;

  if exists (
    select 1 from public.referrals r where r.referee_id = v_caller
  ) then
    raise exception 'you have already redeemed a referral code' using errcode = 'P0001';
  end if;

  select count(*)
    into v_count
    from public.referrals r
   where r.referrer_id = v_owner;

  if v_count >= 5 then
    raise exception 'referral code owner has reached the referral limit' using errcode = 'P0001';
  end if;

  insert into public.referrals (referrer_id, referee_id, created_at)
  values (v_owner, v_caller, pg_catalog.now())
  returning id into v_id;

  insert into public.credits (user_id, amount, reason)
  values
    (v_caller, 100, 'referral_redeemed'),
    (v_owner,  100, 'referral_reward');

  return v_id;
end;
$$;

