-- Redemption RPC (R3, R4)
create or replace function public.redeem_referral(p_code text)
returns bigint
language plpgsql
security definer
set search_path = pg_catalog, public
as $$
declare
  v_caller   uuid := auth.uid();
  v_owner    uuid;
  v_k1       bigint;
  v_k2       bigint;
  v_count    integer;
  v_id       bigint;
begin
  if v_caller is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if p_code is null then
    raise exception 'referral code not found' using errcode = 'P0002';
  end if;

  select rc.user_id
    into v_owner
    from public.referral_codes rc
   where rc.code = p_code;

  if v_owner is null then
    raise exception 'referral code not found' using errcode = 'P0002';
  end if;

  if v_owner = v_caller then
    raise exception 'cannot redeem your own referral code' using errcode = 'P0001';
  end if;

  -- Serialize on both users, in a stable order to avoid deadlocks
  v_k1 := hashtextextended('referral:' || v_caller::text, 0);
  v_k2 := hashtextextended('referral:' || v_owner::text, 0);
  if v_k1 <= v_k2 then
    perform pg_advisory_xact_lock(v_k1);
    if v_k2 <> v_k1 then
      perform pg_advisory_xact_lock(v_k2);
    end if;
  else
    perform pg_advisory_xact_lock(v_k2);
    perform pg_advisory_xact_lock(v_k1);
  end if;

  if exists (
    select 1 from public.referrals r where r.referee_id = v_caller
  ) then
    raise exception 'referral code already redeemed' using errcode = 'P0001';
  end if;

  select count(*)
    into v_count
    from public.referrals r
   where r.referrer_id = v_owner;

  if v_count >= 5 then
