  if new.is_bought is distinct from old.is_bought then
    -- only false -> true reaches here
    if not (old.claimed_by = uid and new.claimed_by = uid) then
      raise exception 'only the claimer can mark an item bought' using errcode = '42501';
    end if;
  end if;

  -- A bought item must remain claimed
  if new.is_bought and new.claimed_by is null then
    raise exception 'a bought item must stay claimed' using errcode = '42501';
  end if;

