    perform pg_advisory_xact_lock(hashtextextended('referral:' || v_caller::text, 0));
  end if;

  if exists (
    select 1 from public.referrals r where r.referee_id = v_caller
  ) then
    raise exception 'you have already redeemed a referral code' using errcode = 'P0001';
  end if;

  select count(*)
    into v_count
    from public.referrals r
   where r.referrer_id = v_referrer;

  if v_count >= 5 then
    raise exception 'this referral code has reached its limit' using errcode = 'P0001';
  end if;

  insert into public.referrals (referrer_id, referee_id, created_at)
  values (v_referrer, v_caller, now())
  returning id into v_referral_id;

  insert into public.credits (user_id, amount, reason)
  values
    (v_caller,   100, 'referral_bonus_referee'),
