-- Enable RLS
alter table public.classes enable row level security;
alter table public.class_spots enable row level security;

-- Privileges: anon gets nothing; authenticated gets only what the app needs
revoke all on public.classes from anon, authenticated;
revoke all on public.class_spots from anon, authenticated;

grant select on public.classes to authenticated;
grant select, delete on public.class_spots to authenticated;
grant insert (class_id, user_id, status) on public.class_spots to authenticated;
grant update (status) on public.class_spots to authenticated;

grant all on public.classes to service_role;
grant all on public.class_spots to service_role;

-- Helper: is there room in the class (ignoring the given user's own spot)?
-- Takes a per-class transaction advisory lock so concurrent joins/promotions
-- serialize and cannot overfill the class. Volatile so the count gets a fresh
-- snapshot after the lock is acquired.
create or replace function public.class_has_room(p_class_id bigint, p_user_id uuid)
returns boolean
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_capacity integer;
  v_enrolled integer;
begin
  perform pg_advisory_xact_lock(p_class_id);

  select c.capacity into v_capacity
  from public.classes c
  where c.id = p_class_id;

  if v_capacity is null then
    return false;
  end if;

  select count(*) into v_enrolled
  from public.class_spots s
  where s.class_id = p_class_id
    and s.status = 'enrolled'
    and s.user_id is distinct from p_user_id;

  return v_enrolled < v_capacity;
end;
$$;

revoke all on function public.class_has_room(bigint, uuid) from public, anon;
grant execute on function public.class_has_room(bigint, uuid) to authenticated, service_role;

-- Helper: does the current user teach this class?
create or replace function public.is_class_instructor(p_class_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.classes c
    where c.id = p_class_id
      and c.instructor_id = auth.uid()
  );
$$;

revoke all on function public.is_class_instructor(bigint) from public, anon;
grant execute on function public.is_class_instructor(bigint) to authenticated, service_role;

-- Trigger: for app users, an update may only move waitlisted -> enrolled,
-- with nothing else changing.
create or replace function public.class_spots_guard_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if current_user in ('authenticated', 'anon') then
    if new.class_id is distinct from old.class_id
       or new.user_id is distinct from old.user_id
       or old.status <> 'waitlisted'
       or new.status <> 'enrolled' then
      raise exception 'Only promoting a waitlisted spot to enrolled is allowed'
        using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;

create trigger class_spots_guard_update
before update on public.class_spots
for each row execute function public.class_spots_guard_update();

-- classes: signed-in users can read; no writes via app
create policy "classes_select_authenticated"
on public.classes
for select
to authenticated
using (true);

-- class_spots: own spots, or all spots in classes the user teaches
create policy "class_spots_select_own_or_instructor"
on public.class_spots
for select
to authenticated
using (
  user_id = auth.uid()
  or public.is_class_instructor(class_id)
);

-- class_spots: join as self; enrolled only when there is room
create policy "class_spots_insert_self"
on public.class_spots
for insert
to authenticated
with check (
  auth.uid() is not null
  and user_id = auth.uid()
  and (
    status = 'waitlisted'
    or (status = 'enrolled' and public.class_has_room(class_id, user_id))
  )
