-- ============================================================
-- Trigger: enforce invariants that policies cannot express
-- (concurrency-safe active-permit limit, per-role column rules,
--  no un-revoke). Runs as invoker so current_user reflects the
--  API role; service_role / internal roles are exempt (R6).
-- ============================================================
create function public.permits_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if current_user not in ('authenticated', 'anon') then
    return coalesce(new, old);
  end if;

  if tg_op = 'INSERT' then
    if new.revoked is distinct from false then
      raise exception 'new permits cannot be revoked';
    end if;
    if new.valid_until > current_date + 365 then
      raise exception 'permit may be valid for at most 365 days';
    end if;
    if not public.is_resident_of(new.unit_id) then
      raise exception 'not a resident of this unit';
    end if;
    -- serialize inserts per unit so the limit cannot be raced
    perform pg_advisory_xact_lock(new.unit_id);
    if public.active_permit_count(new.unit_id) >= 2 then
      raise exception 'unit already has 2 active permits';
    end if;
    return new;

  elsif tg_op = 'UPDATE' then
    if new.id is distinct from old.id
       or new.unit_id is distinct from old.unit_id
       or new.valid_until is distinct from old.valid_until then
      raise exception 'only plate or revoked may be changed';
    end if;
    if old.revoked = true and new.revoked = false then
      raise exception 'permits cannot be un-revoked';
    end if;
    if new.revoked is distinct from old.revoked and not public.is_hoa_admin() then
      raise exception 'only HOA admins can revoke permits';
    end if;
    if new.plate is distinct from old.plate and not public.is_resident_of(old.unit_id) then
      raise exception 'only residents of the unit can change the plate';
    end if;
    return new;

  elsif tg_op = 'DELETE' then
    raise exception 'permits cannot be deleted';
  end if;

  return coalesce(new, old);
end;
$$;

revoke all on function public.permits_guard() from public, anon;

create trigger permits_guard_trg
  before insert or update or delete on public.permits
  for each row execute function public.permits_guard();

