create or replace function public.break_glass(p_patient_id bigint, p_reason text)
returns timestamptz
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_expires timestamptz;
begin
  if v_uid is null
     or not exists (select 1 from public.clinicians c where c.user_id = v_uid) then
    raise exception 'break_glass: caller is not a clinician'
      using errcode = '42501';
  end if;

  if p_patient_id is null
     or not exists (select 1 from public.patients p where p.id = p_patient_id) then
    raise exception 'break_glass: patient does not exist'
      using errcode = 'P0002';
  end if;

  if p_reason is null or char_length(btrim(p_reason)) < 10 then
    raise exception 'break_glass: reason must be at least 10 characters'
      using errcode = '22023';
  end if;

  insert into public.break_glass_grants (patient_id, clinician_id, reason, expires_at)
  values (p_patient_id, v_uid, p_reason, now() + interval '1 hour')
  returning expires_at into v_expires;

  return v_expires;
end;
$$;

