create or replace function public.transfer_stock(
  p_from bigint,
  p_to   bigint,
  p_sku  text,
  p_qty  integer
)
returns integer
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_uid       uuid := auth.uid();
  v_remaining integer;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if p_from is null or p_to is null or p_sku is null or p_qty is null then
    raise exception 'all parameters are required' using errcode = '22004';
  end if;

  if p_qty <= 0 then
    raise exception 'quantity must be positive' using errcode = '22023';
  end if;

  if p_from = p_to then
    raise exception 'destination must differ from source' using errcode = '22023';
  end if;

  if not exists (select 1 from public.warehouse_staff ws
                 where ws.warehouse_id = p_from and ws.user_id = v_uid) then
    raise exception 'not staff of source warehouse' using errcode = '42501';
  end if;

  if not exists (select 1 from public.warehouses w where w.id = p_to) then
    raise exception 'destination warehouse does not exist' using errcode = '23503';
  end if;

  -- Lock existing stock rows in a deterministic order to avoid deadlocks
  perform 1
  from public.stock s
  where s.sku = p_sku
    and s.warehouse_id in (p_from, p_to)
  order by s.warehouse_id
  for update;

  -- Decrement source atomically; fails if missing or insufficient
  update public.stock s
     set qty = s.qty - p_qty
   where s.warehouse_id = p_from
     and s.sku = p_sku
     and s.qty >= p_qty
  returning s.qty into v_remaining;

  if not found then
    raise exception 'insufficient stock at source' using errcode = 'P0001';
  end if;

  -- Credit destination (create row if needed)
  insert into public.stock (warehouse_id, sku, qty)
  values (p_to, p_sku, p_qty)
  on conflict (warehouse_id, sku)
  do update set qty = public.stock.qty + excluded.qty;

  -- Record the transfer by the caller
  insert into public.transfers (from_warehouse, to_warehouse, sku, qty, moved_by)
  values (p_from, p_to, p_sku, p_qty, v_uid);

  return v_remaining;
end;
$$;

