  p_org_id bigint,
  p_user_id uuid,
  p_role text
)
returns text
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_caller uuid := auth.uid();
  v_caller_role text;
  v_target_role text;
  r record;
begin
  if v_caller is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  if p_org_id is null or p_user_id is null or p_role is null then
    raise exception 'invalid arguments' using errcode = '22023';
  end if;

  if p_role not in ('admin', 'member') then
    raise exception 'invalid role: %', p_role using errcode = '22023';
  end if;

  if p_user_id = v_caller then
    raise exception 'cannot change your own role' using errcode = '42501';
  end if;

  -- Lock both rows in a deterministic order to serialize concurrent changes.
  for r in
    select m.user_id, m.role
    from public.org_members m
    where m.org_id = p_org_id
      and m.user_id in (v_caller, p_user_id)
    order by m.user_id
    for update
  loop
    if r.user_id = v_caller then
      v_caller_role := r.role;
    else
      v_target_role := r.role;
    end if;
  end loop;

  if v_caller_role is null or v_caller_role not in ('owner', 'admin') then
    raise exception 'permission denied: caller is not an owner or admin of this organization'
      using errcode = '42501';
  end if;

  if v_target_role is null then
    raise exception 'target user is not a member of this organization'
      using errcode = '42501';
  end if;

  if v_target_role = 'owner' then
    raise exception 'cannot change the role of an owner'
      using errcode = '42501';
  end if;

  update public.org_members
     set role = p_role
   where org_id = p_org_id
     and user_id = p_user_id;

  return p_role;
end;
$$;

