  select m.user_id, count(*)::integer
  from public.org_members m
  group by m.user_id
  on conflict (user_id) do update
    set score = excluded.score;

  update public.leaderboard l
     set score = 0
   where not exists (
     select 1 from public.org_members m where m.user_id = l.user_id
   );
end;
$$;

